const input = $json;

const sessionId = String(input.session_id || 'default');
const name = String(input.name || 'New Employee');
const role = String(input.role || 'Not provided');
const department = String(input.department || 'Not provided');
const location = String(input.location || 'Not provided');
const startDate = String(input.start_date || 'Not provided');

// Get question from the HTML Form
const question = String(
  input.question ||
  input["Your Question"] ||
  ""
).trim();

if (!question) {
  throw new Error(
    'Question is required. Please enter a question in the HTML form.'
  );
}

const store = $getWorkflowStaticData('global');

if (!store.sessions) {
  store.sessions = {};
}

if (!store.sessions[sessionId]) {
  store.sessions[sessionId] = [];
}

const history = store.sessions[sessionId].slice(-8);

const systemPrompt = `You are an Employee Onboarding Concierge.

Your purpose is to help new employees during onboarding.

You can help with:
- onboarding questions
- first-week tasks
- IT access
- policy acknowledgement
- training
- onboarding schedule
- documents
- HR questions
- onboarding progress

Be friendly, concise and practical.

Do not invent company-specific policies, deadlines,
documents, salary information or confidential employee information.

If information is not available, recommend contacting HR,
the manager, or IT.

Return plain text only.
Use short headings and bullet points when useful.`;

const userMessage = `Employee profile:
Name: ${name}
Role: ${role}
Department: ${department}
Location: ${location}
Start Date: ${startDate}

Current question:
${question}`;

const messages = [
  {
    role: 'system',
    content: systemPrompt
  },
  ...history,
  {
    role: 'user',
    content: userMessage
  }
];

return [{
  json: {
    session_id: sessionId,
    name,
    role,
    department,
    location,
    start_date: startDate,
    question,
    messages
  }
}];

const groq = $json;

const answer =
  groq.choices?.[0]?.message?.content ||
  'Sorry, I could not generate a response.';

const input = $('Prepare AI Request + Memory').first().json;
const sessionId = input.session_id;

// Save the current conversation into simple memory.
const store = $getWorkflowStaticData('global');

if (!store.sessions) {
  store.sessions = {};
}

if (!store.sessions[sessionId]) {
  store.sessions[sessionId] = [];
}

store.sessions[sessionId].push(
  {
    role: 'user',
    content: input.question
  },
  {
    role: 'assistant',
    content: answer
  }
);

// Keep memory small.
store.sessions[sessionId] =
  store.sessions[sessionId].slice(-8);

return [{
  json: {
    session_id: sessionId,
    name: input.name,
    role: input.role,
    department: input.department,
    location: input.location,
    question: input.question,
    answer
  }
}];
